 static readonly (double Fraction,string Color)[] ringColors={(0,"#17233F"),(.16,"#354064"),(.23,"#A39AB7"),(.28,"#E7BC85"),(.34,"#ACD5E7"),(.50,"#BFE2EF"),(.65,"#AFD4E4"),(.74,"#E8B581"),(.81,"#AC819F"),(.89,"#343B5B"),(1,"#17233F")};
 static readonly Color[] ringPalette=ringColors.Select(c=>(Color)ColorConverter.ConvertFromString(c.Color)).ToArray();
 static Color RingColor(double fraction,double opacity){fraction=(fraction%1+1)%1;int i=0;while(i<ringColors.Length-2&&ringColors[i+1].Fraction<fraction)i++;var a=ringPalette[i];var b=ringPalette[i+1];double t=(fraction-ringColors[i].Fraction)/(ringColors[i+1].Fraction-ringColors[i].Fraction);return Color.FromArgb((byte)Math.Round(255*opacity),(byte)(a.R+(b.R-a.R)*t),(byte)(a.G+(b.G-a.G)*t),(byte)(a.B+(b.B-a.B)*t));}
 static readonly Color[] ringRgb=Enumerable.Range(0,4096).Select(i=>RingColor(i/4096d,1)).ToArray();
 BitmapSource? ringGradient;double gradientSize=-1,gradientOpacity=-1;
 BitmapSource RingGradient(){if(ringGradient!=null&&gradientSize==Width&&gradientOpacity==BackgroundOpacity)return ringGradient;int size=(int)Math.Ceiling(Width);double center=Width/2,radius=RingLayout.Radius(Width),half=RingLayout.HalfThickness(Width),opacity=BackgroundOpacity;var pixels=new byte[size*size*4];for(int y=0;y<size;y++)for(int x=0;x<size;x++){double dx=x+.5-center,dy=y+.5-center,d=Math.Sqrt(dx*dx+dy*dy);double edge=Math.Clamp(Math.Min(d-(radius-half),(radius+half)-d),0,1);if(edge<=0)continue;double fraction=(Math.Atan2(dx,-dy)/(Math.PI*2)+1)%1;var color=ringRgb[Math.Min(4095,(int)(fraction*4096))];byte alpha=(byte)Math.Round(255*opacity*edge);int at=(y*size+x)*4;pixels[at]=(byte)(color.B*alpha/255);pixels[at+1]=(byte)(color.G*alpha/255);pixels[at+2]=(byte)(color.R*alpha/255);pixels[at+3]=alpha;}ringGradient=BitmapSource.Create(size,size,96,96,PixelFormats.Pbgra32,null,pixels,size*4);ringGradient.Freeze();gradientSize=Width;gradientOpacity=BackgroundOpacity;return ringGradient;}
 static Geometry RingWedge(double a,double b,double inner,double outer,Point center){var g=new StreamGeometry();using(var c=g.Open()){c.BeginFigure(RingLayout.PointAt(a,outer,center),true,true);c.ArcTo(RingLayout.PointAt(b,outer,center),new Size(outer,outer),0,false,SweepDirection.Clockwise,true,false);c.LineTo(RingLayout.PointAt(b,inner,center),true,false);c.ArcTo(RingLayout.PointAt(a,inner,center),new Size(inner,inner),0,false,SweepDirection.Counterclockwise,true,false);}g.Freeze();return g;}
