  for(int h=0;h<24;h++){int level=TickLevel(h);double f=h/24d;var a=RingLayout.PointAt(f,radius-(level==2?20:level==1?16:12),center);var b=RingLayout.PointAt(f,radius-6,center);ring.Children.Add(new Line{X1=a.X,Y1=a.Y,X2=b.X,Y2=b.Y,Stroke=Brush("#B8172940"),StrokeThickness=level==2?4:level==1?3:2,IsHitTestVisible=false});ring.Children.Add(new Line{X1=a.X,Y1=a.Y,X2=b.X,Y2=b.Y,Stroke=Brush(h==12?"#FFE2A0":h==0?"#C7DAFF":"#E5F0F8"),StrokeThickness=level==2?2:level==1?1.5:.8,IsHitTestVisible=false});if(h%6==0||Width>=560&&h%3==0){var at=RingLayout.PointAt(f,Math.Max(25,radius-half-20),center);bool major=h%6==0;double w=major?64:host.S.Twelve?52:28;var label=LightText(TickLabel(h,host.S.Twelve),major?12:10,w,17,h==12?"#FFE0A1":"#E8F1FA",major);Canvas.SetLeft(label,at.X-w/2);Canvas.SetTop(label,at.Y-(major?17:8));ring.Children.Add(label);if(major){var period=LightText(ClockPeriod.CardinalName(h,host.S.Language),9.5,64,14,"#E4EEF9");Canvas.SetLeft(period,at.X-32);Canvas.SetTop(period,at.Y+1);ring.Children.Add(period);}}}
  var grip=RingLayout.PointAt(22.7/24,radius,center);for(int i=-1;i<=1;i++){var dot=new Ellipse{Width=2.5,Height=2.5,Fill=Brush("#D9E9F6"),IsHitTestVisible=false};Canvas.SetLeft(dot,grip.X+i*5-1.25);Canvas.SetTop(dot,grip.Y-1.25);ring.Children.Add(dot);}
  ChooseRingResizeGrip();ringResizePad=new Path{Data=RingGripArc(),Stroke=Brush("#FFF0D2A0"),StrokeThickness=2,StrokeStartLineCap=PenLineCap.Round,StrokeEndLineCap=PenLineCap.Round,Opacity=ResizeHovered?1:.85,IsHitTestVisible=false};ring.Children.Add(ringResizePad);ringResizeGlyph=LightText("↔",15,20,20,"#FFBE55",true);ringResizeGlyph.Opacity=1;Canvas.SetLeft(ringResizeGlyph,RingResizePoint.X-10);Canvas.SetTop(ringResizeGlyph,RingResizePoint.Y-10);ring.Children.Add(ringResizeGlyph);
  PersonDates=ringNodes.Where(n=>!n.Date.IsEmpty).Select(n=>new RulerPersonDate(n.Cluster,n.Date)).ToArray();
  foreach(var n in ringNodes){var c=n.Cluster;var p=n.Person;string accent=p.Self?"#E4BF7C":"#BED3E1";var anchor=RingLayout.PointAt(p.Fraction,n.Inset?inner:outer,center);var direction=n.Center-anchor;double length=direction.Length;if(length>20){direction.Normalize();var end=n.Center-direction*19;ring.Children.Add(new Line{X1=anchor.X,Y1=anchor.Y,X2=end.X,Y2=end.Y,Stroke=Brush(p.Self?"#EDC880":"#A6BFDA"),StrokeThickness=1,IsHitTestVisible=false});}
   foreach(var member in c.Members){var pinAt=RingLayout.PointAt(member.Fraction,outer,center);var pin=new Ellipse{Width=member.Self?4:2.5,Height=member.Self?4:2.5,Fill=Brush(member.Self?"#F4D094":"#C9E0ED"),IsHitTestVisible=false};Canvas.SetLeft(pin,pinAt.X-pin.Width/2);Canvas.SetTop(pin,pinAt.Y-pin.Height/2);ring.Children.Add(pin);}
