   var avatar=new Button{Width=AvatarSize+4,Height=AvatarSize+4,Content=portrait,Template=AvatarFrame(),Padding=new Thickness(1),Background=Brush("#F9FAFC"),BorderBrush=Brush(accent),BorderThickness=new Thickness(1.5),ToolTip=ClusterTip(c),Tag=c};AutomationProperties.SetName(avatar,p.Name+" "+p.Time(host.S.Twelve));avatar.Click+=(_,_)=>{flyoutPoint=Desktop.Position;OpenCluster(c,avatar);};Canvas.SetLeft(avatar,n.Center.X-17);Canvas.SetTop(avatar,n.Center.Y-17);ring.Children.Add(avatar);foreach(var member in c.Members)PersonButtons[member.Id]=avatar;
   var halo=new Ellipse{Width=42,Height=42,Stroke=Brushes.Transparent,StrokeThickness=2,IsHitTestVisible=false};Canvas.SetLeft(halo,n.Center.X-21);Canvas.SetTop(halo,n.Center.Y-21);ring.Children.Add(halo);
   var copy=new StackPanel();copy.Children.Add(LightText(p.Name+(c.Members.Count>1?" +"+(c.Members.Count-1):""),10.5,n.Label.Width,14,p.Self?"#FFE0A1":"#F3F7FC",true));copy.Children.Add(LightText(p.Time(host.S.Twelve),13,n.Label.Width,18,"#F7FAFF",true));copy.Children.Add(LightText(n.Date.IsEmpty?ClockPeriod.Name(p.Local.Hour*60+p.Local.Minute,host.S.Language):DateCaption(p),10,n.Label.Width,14,p.Self?"#FFE0A1":"#DDECF9"));var label=new Border{Width=n.Label.Width,Height=n.Label.Height,Background=Brushes.Transparent,Child=copy,ToolTip=ClusterTip(c)};Canvas.SetLeft(label,n.Label.X);Canvas.SetTop(label,n.Label.Y);ring.Children.Add(label);personInk.Add(new(c,avatar,halo,label));
   if(!n.Date.IsEmpty){var date=new Border{Width=n.Date.Width,Height=n.Date.Height,Background=Brushes.Transparent,BorderBrush=Brushes.Transparent,BorderThickness=new Thickness(.5),ToolTip=DateTip(PersonDates.First(d=>d.Person.Id==p.Id))};Canvas.SetLeft(date,n.Date.X);Canvas.SetTop(date,n.Date.Y);ring.Children.Add(date);dateInk[p.Id]=date;}
  }ApplyDateHighlight();
 }
 OutlinedLabel? ringResizeGlyph;
 Path? ringResizePad;
 string RingTickTip(Point p){var center=new Point(Width/2,Width/2);double radius=RingLayout.Radius(Width);var delta=p-center;if(Math.Abs(delta.Length-radius)>45)return "";double f=(Math.Atan2(delta.X,-delta.Y)/(Math.PI*2)+1)%1;int h=(int)Math.Round(f*24)%24;return ClockPeriod.Tick(h,host.S.Language,host.S.Twelve);}
 void DrawRingAmbience(DrawingContext dc,double t){
  if(!NatureEnabled||BackgroundOpacity<=0)return;var center=new Point(Width/2,Width/2);double radius=RingLayout.Radius(Width);var safe=Geometry.Combine(new EllipseGeometry(center,radius+RingLayout.HalfThickness(Width)-2,radius+RingLayout.HalfThickness(Width)-2),new EllipseGeometry(center,Math.Max(1,radius+1),Math.Max(1,radius+1)),GeometryCombineMode.Exclude,null);dc.PushClip(safe);dc.PushOpacity(BackgroundOpacity);
  Point At(double h)=>RingLayout.PointAt(h/24,radius+RingLayout.HalfThickness(Width)-6,center);
  int i=0;foreach(double h in new[]{2.5,4,20.6,21.4}){var p=At(h);var pen=new Pen(MotionBrush("#F0F6FF",.65+.25*Math.Sin(t*.55+i++*1.9)),.85);dc.DrawLine(pen,p+new Vector(-1.5,0),p+new Vector(1.5,0));dc.DrawLine(pen,p+new Vector(0,-1.5),p+new Vector(0,1.5));}
  foreach(double h in new[]{1.3,22.5}){var p=At(h);double pulse=.5+.5*Math.Sin(t*.48+h);dc.DrawEllipse(MotionBrush("#CFE2FF",.08+.07*pulse),null,p,5.7,5.7);dc.PushTransform(new TranslateTransform(p.X,p.Y));dc.PushTransform(new ScaleTransform(.65,.65));dc.DrawGeometry(MotionBrush("#EEF6FF"),null,moonShape);dc.Pop();dc.Pop();}
  var sun=At(12);dc.DrawEllipse(MotionBrush("#FFDA8A",.1+.06*Math.Sin(t*.42)),null,sun,6,6);dc.DrawEllipse(MotionBrush("#FFF0BD"),null,sun,3,3);
  foreach(double start in new[]{8.5,15d}){double h=EffectiveMotionMode==RulerMotionMode.Dynamic?6.5+(start-6.5+t*.035)%11:start;double fade=Math.Clamp(Math.Min(h-6.5,17.5-h)/.8,0,1);var p=At(h);dc.PushOpacity(fade*.8);dc.PushTransform(new TranslateTransform(p.X-6,p.Y-3));dc.PushTransform(new ScaleTransform(.52,.52));dc.DrawGeometry(MotionBrush("#F0FAFF"),null,CloudGeometry);dc.Pop();dc.Pop();dc.Pop();}
  dc.Pop();dc.Pop();
